/* SpaceEdu service worker.
 *
 * Deliberately hand-written rather than generated by next-pwa: the plugin
 * broke the Vercel build, and all this app needs from a worker is enough
 * offline behaviour to satisfy the install criteria and to keep static
 * assets available when the network drops.
 *
 * What it will NOT cache, and why: anything under /api, anything that is
 * not a plain GET, and any response the server marked private or set a
 * cookie on. The previous version cached every successful GET, which put
 * signed-in HTML and API JSON into a cache that survives sign-out — on a
 * shared computer the next person could be served the last person's
 * dashboard out of it.
 */

const CACHE_NAME = "spaceedu-pwa-v3";

/** Caches from older versions of this worker, cleared on activate. */
const KEEP = new Set([CACHE_NAME]);

self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => !KEEP.has(key)).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

/** Only static, public things are worth keeping offline. */
function isCacheable(request, response) {
  if (request.method !== "GET") return false;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return false;
  if (url.pathname.startsWith("/api/")) return false;

  if (!response || !response.ok || response.type !== "basic") return false;

  // Anything the server marked as belonging to one user stays out.
  const cacheControl = response.headers.get("Cache-Control") || "";
  if (/(^|,)\s*(private|no-store)/i.test(cacheControl)) return false;
  if (response.headers.has("Set-Cookie")) return false;

  // Documents are per-user on most of this site; serve them from the
  // network only, and let the browser's own back/forward cache do the rest.
  if (request.destination === "document") return false;

  return true;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  event.respondWith(
    fetch(request)
      .then((response) => {
        if (isCacheable(request, response)) {
          const copy = response.clone();
          void caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
        }
        return response;
      })
      .catch(async () => {
        const cached = await caches.match(request);
        return cached || Response.error();
      }),
  );
});
